const { STROC_JSON } = process.env;
if (!STROC_JSON) {
  throw new Error('Missing STROC_JSON');
}
try {
  globalThis.strocDoc = JSON.parse(STROC_JSON);
} catch (e) {
  throw new Error('Invalid STROC_JSON');
}

const mod = await import('@stroc/pdf');
const { toPdf } = mod;
const bytes = await toPdf(globalThis.strocDoc, { pageSize: 'A4' });
globalThis.pdfBase64 = Buffer.from(bytes).toString('base64');
